// --- Auth Bouncer (Code node) ---
// Runs after "Verify Firebase Token", which asked Google to check the ID token.
// Any userId or email sent by the client is dropped and replaced.
// Mode: Run Once for All Items.
const IDENTITY_FIELDS = ['userId', 'email']

const users = $input.first().json.users || []
if (!users.length) throw new Error('UNAUTHORIZED: no Firebase user for this token')
const verifiedUser = users[0]

// --- Output: the request body plus the verified identity ---
const requestBody = $('Read Webhook').first().json.body || {}
const safeBody = Object.fromEntries(
  Object.entries(requestBody).filter(([key]) => !IDENTITY_FIELDS.includes(key)),
)
return [{ json: { ...safeBody, userId: verifiedUser.localId, email: verifiedUser.email ?? null } }]

// --- Shape Read Response (Code node, Read API) ---
// Input: Get User Bundle aggregate (profile[], transactions[], goals[], request).
// Mode: Run Once for All Items. Steps 1-2 mirror the Affordability Algorithm; change both together.
const DEFAULT_LIMIT = 50
const MAX_LIMIT = 200
// Suggested grouping of transaction categories (team can edit)
const EXPENSE_GROUPS = {
  essential: new Set(['groceries', 'rent', 'utilities', 'transport', 'fuel', 'telecom', 'health', 'education']),
  adjustable: new Set(['dining', 'clothing', 'household', 'subscriptions']),
  optional: new Set(['entertainment', 'gifts', 'festival', 'other']),
}

// Python-style rounding (half to even), so amounts match the earlier Python version exactly.
function pyRound(value) {
  const floor = Math.floor(value)
  const diff = value - floor
  if (diff > 0.5) return floor + 1
  if (diff < 0.5) return floor
  return floor % 2 === 0 ? floor : floor + 1
}

// Mauritius time: UTC+4, no daylight saving.
function mauritiusNow(offsetDays = 0) {
  const shifted = new Date(Date.now() + 4 * 3600e3 + offsetDays * 86400e3).toISOString()
  return { date: shifted.slice(0, 10), stamp: shifted.slice(0, 19) + '+04:00' }
}

// --- Input ---
const bundle = $input.first().json
const request = bundle.request || {}
const action = request.inputType
const profileRows = bundle.profile || []
let profile = profileRows.length ? profileRows[0] : null
const txns = bundle.transactions || []
const goals = bundle.goals || []
const today = mauritiusNow().date
const since30 = mauritiusNow(-30).date
const profileComplete = Boolean(profile && Object.keys(profile).length) && profile.salary !== undefined && profile.salary !== null

const toInt = (value) => Math.trunc(Number(value || 0))
// Newest first: by date, then by creation time (stable, like the Python version).
const newestFirst = (rows) => [...rows].sort((a, b) => {
  const keyA = [String(a.txnDate || ''), String(a.createdAt || '')]
  const keyB = [String(b.txnDate || ''), String(b.createdAt || '')]
  if (keyA[0] !== keyB[0]) return keyA[0] < keyB[0] ? 1 : -1
  if (keyA[1] !== keyB[1]) return keyA[1] < keyB[1] ? 1 : -1
  return 0
})
const txnView = (t) => ({
  id: t.id ?? null, txnDate: t.txnDate ?? null, amountCents: toInt(t.amount), direction: t.direction ?? null,
  category: t.category ?? null, vendor: t.vendor ?? null, name: t.name ?? null, source: t.source ?? null,
  docType: t.docType ?? null, isRoutine: Boolean(t.isRoutine),
})
const respond = (data) => [{ json: { success: true, record: action ?? null, data } }]

// --- getProfile ---
if (action === 'getProfile') return respond({ profileComplete, profile })

// --- listGoals ---
if (action === 'listGoals') {
  const rows = [...goals].sort((a, b) => {
    const keyA = String(a.updatedAt || ''), keyB = String(b.updatedAt || '')
    return keyA === keyB ? 0 : keyA < keyB ? 1 : -1
  })
  return respond({ count: rows.length, goals: rows.map((g) => ({
    id: g.id ?? null, goalKey: g.goalKey ?? null, itemName: g.itemName ?? null,
    goalType: g.goalType ?? null, targetAmountCents: toInt(g.targetAmount),
    savedAmountCents: toInt(g.savedAmount),
    verdict: g.verdict ?? null, status: g.status ?? null,
    timelineMonths: g.timelineMonths ?? null, link: g.link ?? null,
    updatedAt: g.updatedAt ?? null,
  })) })
}

// --- listTransactions (filters: month YYYY-MM, category, direction; limit) ---
if (action === 'listTransactions') {
  let limit = Math.trunc(Number(request.limit || DEFAULT_LIMIT))
  if (!Number.isFinite(limit)) limit = DEFAULT_LIMIT
  limit = Math.min(Math.max(limit, 1), MAX_LIMIT)
  let rows = txns
  if (request.month) rows = rows.filter((t) => String(t.txnDate || '').startsWith(request.month))
  if (request.category) rows = rows.filter((t) => t.category === request.category)
  if (request.direction) rows = rows.filter((t) => t.direction === request.direction)
  rows = newestFirst(rows)
  return respond({ totalCount: rows.length, returned: Math.min(limit, rows.length), transactions: rows.slice(0, limit).map(txnView) })
}

// --- getDashboard ---
// Step 1 (as Affordability): inferred balance
profile = profile || {}
let balance = 0
let recent = txns
if (profile.manualBalance !== undefined && profile.manualBalance !== null) {
  balance = Math.trunc(Number(profile.manualBalance))
  const cutoff = String(profile.manualBalanceDate || '')
  recent = txns.filter((t) => String(t.txnDate) > cutoff)
}
for (const t of recent) {
  const amount = Math.trunc(Number(t.amount ?? 0))
  balance += t.direction === 'income' ? amount : -amount
}

// Step 2 (as Affordability): usual monthly spending
// The user's own monthly expense list wins; otherwise estimate from repeat expenses.
const declaredExpenses = (profile.monthlyExpenses || []).filter((e) => e && typeof e === 'object' && !Array.isArray(e))
let monthlyRoutine
if (declaredExpenses.length) {
  monthlyRoutine = declaredExpenses.reduce((sum, e) => sum + toInt(e.amountCents), 0)
} else {
  const routine = txns.filter((t) => t.isRoutine && t.direction === 'expense')
  const monthsSeen = new Set(routine.map((t) => String(t.txnDate).slice(0, 7))).size || 1
  monthlyRoutine = Math.floor(routine.reduce((sum, t) => sum + Math.trunc(Number(t.amount ?? 0)), 0) / monthsSeen)
}
const salary = toInt(profile.salary)

const last30 = txns.filter((t) => since30 <= String(t.txnDate || '') && String(t.txnDate || '') <= today)
const breakdown = {}
for (const t of last30) {
  if (t.direction === 'expense') {
    const category = t.category || 'other'
    breakdown[category] = (breakdown[category] || 0) + toInt(t.amount)
  }
}
const groups = Object.fromEntries(Object.entries(EXPENSE_GROUPS).map(([name, cats]) => [
  name, Object.entries(breakdown).filter(([k]) => cats.has(k)).reduce((sum, [, v]) => sum + v, 0),
]))
const statusCounts = {}
for (const g of goals) statusCounts[g.status || 'unknown'] = (statusCounts[g.status || 'unknown'] || 0) + 1

return respond({
  asOf: today,
  profileComplete,
  salaryCents: salary,
  inferredBalanceCents: balance,
  monthlyRoutineCents: monthlyRoutine,
  spendingSource: declaredExpenses.length ? 'declared' : 'history',
  monthlyExpenses: declaredExpenses.map((e) => ({ name: e.name ?? null, amountCents: toInt(e.amountCents), group: e.group ?? null })),
  safeSavingCapacityCents: salary - monthlyRoutine,
  expensesLast30DaysCents: Object.values(breakdown).reduce((sum, v) => sum + v, 0),
  incomeLast30DaysCents: last30.filter((t) => t.direction === 'income').reduce((sum, t) => sum + toInt(t.amount), 0),
  expenseBreakdownCents: Object.fromEntries(Object.entries(breakdown).sort((a, b) => b[1] - a[1])),
  expenseGroupsCents: groups,
  activeGoals: goals.length,
  goalsByStatus: statusCounts,
  recentTransactions: newestFirst(txns).slice(0, 5).map(txnView),
  hasHistory: txns.length > 0,
})
